arguments.file_text:
@page "/chat"
@using sv_017ce42401354cd3aecb66751cdc8fdf.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="sidebar-panel">
        <ChannelSidebar Channels="channels"
                        SelectedChannelId="selectedChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="main-panel">
        @if (selectedChannel is not null)
        {
            <div class="channel-header">
                <h2># @selectedChannel.Name</h2>
                <span class="channel-description">@selectedChannel.Description</span>
            </div>

            <div class="message-list">
                @if (hasMoreMessages)
                {
                    <div class="load-more-container">
                        <button class="load-more-btn" @onclick="LoadOlderMessages" disabled="@loadingMore">
                            @(loadingMore ? "Loading..." : "Load older messages")
                        </button>
                    </div>
                }

