    private Channel? selectedChannel;
    private int selectedChannelId;
    private Message? threadRootMessage;
    private bool isThreadOpen;
    private bool loading;
    private bool loadingMore;
    private bool hasMoreMessages;
    private const int PageSize = 30;

    // Track reply counts: rootMessageId → count
    private Dictionary<int, int> replyCounts = new();

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        if (selectedChannelId == channelId && selectedChannel is not null) return;

        selectedChannelId = channelId;
        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messages = [];
        replyCounts = new();
        loading = true;

        CloseThreadSync();

        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        hasMoreMessages = messages.Count >= PageSize;
        ComputeReplyCounts();
        loading = false;

        await ChatService.MarkChannelReadAsync(channelId);

        // Update unread count locally
        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            channels[idx] = channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task LoadOlderMessages()
    {
        if (loadingMore || selectedChannel is null) return;
        loadingMore = true;

        var older = await ChatService.GetMessagesAsync(selectedChannelId, messages.Count, PageSize);
        hasMoreMessages = older.Count >= PageSize;

        // Prepend older messages
        messages.InsertRange(0, older);
        ComputeReplyCounts();
        loadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannel is null) return;
        var msg = await ChatService.SendMessageAsync(selectedChannelId, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(Message rootMessage)
    {
        // If the message itself is a reply, find its root or just use it as thread root
        threadRootMessage = rootMessage;
        threadReplies = await ChatService.GetThreadAsync(rootMessage.Id);
        isThreadOpen = true;
    }

    private void CloseThread()
    {
        CloseThreadSync();
    }

    private void CloseThreadSync()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null || selectedChannel is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannelId, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update reply count
        replyCounts[threadRootMessage.Id] = threadReplies.Count;
    }

    private async Task AddReaction(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);

        // Optimistically update the local message
        var msg = messages.FirstOrDefault(m => m.Id == messageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
            if (existing is not null)
            {
                if (!existing.Users.Contains("You"))
                    existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(emoji, ["You"]));
            }
        }
    }

    private void ComputeReplyCounts()
    {
        replyCounts.Clear();
        foreach (var msg in messages)
        {
            if (msg.ReplyToId is int rootId)
            {
                replyCounts[rootId] = replyCounts.GetValueOrDefault(rootId) + 1;
            }
        }
    }

    private int GetReplyCount(int messageId) =>
        replyCounts.GetValueOrDefault(messageId);
}

