toolArgs.file_text:
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    background-color: #313338;
    color: #e0e0e0;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.sidebar-panel {
    width: 20%;
    min-width: 200px;
    flex-shrink: 0;
}

.main-panel {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    background-color: #313338;
}

.thread-panel-container {
    width: 25%;
    min-width: 280px;
    flex-shrink: 0;
}

/* Channel header */
.channel-header {
    padding: 14px 20px;
    border-bottom: 1px solid #1e1f22;
    display: flex;
    align-items: baseline;
    gap: 12px;
    flex-shrink: 0;
}

.channel-header h2 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #e0e0e0;
}

.channel-description {
    font-size: 0.82rem;
    color: #72767d;
}

/* Message list */
.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 0;
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.load-more-container {
    text-align: center;
    padding: 8px;
}

.load-more-btn {
    background: none;
    border: 1px solid #4a4a4a;
    color: #b5bac1;
    padding: 6px 16px;
    border-radius: 6px;
    font-size: 0.82rem;
    cursor: pointer;
    transition: all 0.15s;
}

.load-more-btn:hover:not(:disabled) {
    background-color: rgba(255, 255, 255, 0.06);
    color: #e0e0e0;
}

.load-more-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.empty-state,
.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    color: #72767d;
    font-size: 1rem;
}

.no-channel-selected p {
    margin: 0;
}

