+    padding: 6px 16px;
+    border-radius: 6px;
+    font-size: 0.82rem;
+    cursor: pointer;
+    transition: all 0.15s;
+}
+
+.load-more-btn:hover:not(:disabled) {
+    background-color: rgba(255, 255, 255, 0.06);
+    color: #e0e0e0;
+}
+
+.load-more-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+.empty-state,
+.no-channel-selected {
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    flex: 1;
+    color: #72767d;
+    font-size: 1rem;
+}
+
+.no-channel-selected p {
+    margin: 0;
+}
